CREATE TABLE IF NOT EXISTS platform_credentials(player_id VARCHAR(64) PRIMARY KEY,username VARCHAR(32) NOT NULL UNIQUE,password_hash CHAR(64) NOT NULL,salt VARCHAR(64) NOT NULL,created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS game_listings(game_id VARCHAR(64) PRIMARY KEY,summary VARCHAR(256) NOT NULL,description TEXT NOT NULL,category VARCHAR(32) NOT NULL,accent VARCHAR(24) NOT NULL,icon VARCHAR(32) NOT NULL,version VARCHAR(32) NOT NULL,entry_url VARCHAR(256) NOT NULL,companion_level VARCHAR(32) NOT NULL,published BOOLEAN NOT NULL DEFAULT FALSE,draft JSON NULL,draft_author VARCHAR(64) NOT NULL DEFAULT '',submitted BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS player_library(player_id VARCHAR(64) NOT NULL,game_id VARCHAR(64) NOT NULL,favorite BOOLEAN NOT NULL DEFAULT FALSE,last_played_at BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(player_id,game_id));
CREATE TABLE IF NOT EXISTS launch_grants(code_hash CHAR(64) PRIMARY KEY,player_id VARCHAR(64) NOT NULL,game_id VARCHAR(64) NOT NULL,parent_hash CHAR(64) NOT NULL,code_challenge VARCHAR(64) NOT NULL,expires_at BIGINT NOT NULL,consumed BOOLEAN NOT NULL DEFAULT FALSE,INDEX launch_expiry(expires_at));
CREATE TABLE IF NOT EXISTS game_sessions(token_hash CHAR(64) PRIMARY KEY,player_id VARCHAR(64) NOT NULL,game_id VARCHAR(64) NOT NULL,parent_hash CHAR(64) NOT NULL,expires_at BIGINT NOT NULL,INDEX game_session_expiry(expires_at),INDEX game_session_parent(parent_hash));
